    if (!com.bloo.bluelink.BuildConfig.PLAY_DISTRIBUTION) {
        val intent = Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS)
            .setData("package:${context.packageName}".toUri())
